mapper.select:
SELECT PTL_ID, VAL_DATE, totalAssestCost, totalAssestValue, netAssestCost, netAssestValue, unitNetWorthCost, unitNetWorthValue, comparedWithDay, comparedWithMonth, comparedWithYear, deviatingAmount, degreeOfDeviate, T1.ASSET_NAME AS PORTFOLIO_NAME FROM ( SELECT DISTINCT A.PTL_ID AS PTL_ID, A.VAL_DATE, D.ZQ_Cost AS totalAssestCost, D.ZQ_Value AS totalAssestValue, E.ZQ_Cost AS netAssestCost, E.ZQ_Value AS netAssestValue, F.ZQ_Cost AS unitNetWorthCost, F.ZQ_Value AS unitNetWorthValue, ROUND( ( F.ZQ_Cost - DAY.ZQ_Cost ) / F.ZQ_Cost, 4 ) * 100 AS comparedWithDay, ROUND( ( F.ZQ_Cost - MONTH.ZQ_Cost ) / F.ZQ_Cost, 4 ) * 100 AS comparedWithMonth, ROUND( ( F.ZQ_Cost - YEAR.ZQ_Cost ) / F.ZQ_Cost, 4 ) * 100 AS comparedWithYear, E.ZQ_Value - E.ZQ_Cost AS deviatingAmount, ( ( E.ZQ_Value - E.ZQ_Cost ) / E.ZQ_Cost ) * 100 AS degreeOfDeviate FROM ( SELECT DISTINCT VAL_DATE, PTL_ID FROM RSK_VALTBL_SUM_ASSET_SUB WHERE SUB_CODE = '604'
AND VAL_DATE = STR_TO_DATE(#{valDate},'%Y-%m-%d')
) A LEFT JOIN ( SELECT SECURITY_COST ZQ_Cost, SMV ZQ_Value, VAL_DATE, PTL_ID FROM RSK_VALTBL_SUM_ASSET_SUB WHERE SUB_CODE = '604' ) D ON D.PTL_ID = A.PTL_ID AND D.VAL_DATE = A.VAL_DATE LEFT JOIN ( SELECT SECURITY_COST AS ZQ_Cost, SMV AS ZQ_Value, VAL_DATE, PTL_ID FROM RSK_VALTBL_SUM_ASSET_SUB WHERE SUB_CODE = '701' ) E ON E.PTL_ID = A.PTL_ID AND E.VAL_DATE = A.VAL_DATE LEFT JOIN ( SELECT SECURITY_COST AS ZQ_Cost, SMV AS ZQ_Value, VAL_DATE, PTL_ID FROM RSK_VALTBL_SUM_ASSET_SUB WHERE SUB_CODE = '702' ) F ON F.PTL_ID = A.PTL_ID AND F.VAL_DATE = A.VAL_DATE LEFT JOIN ( SELECT SECURITY_COST AS ZQ_Cost, SMV AS ZQ_Value, VAL_DATE, PTL_ID FROM RSK_VALTBL_SUM_ASSET_SUB WHERE SUB_CODE = '702'
AND VAL_DATE = STR_TO_DATE(#{previousDay},'%Y-%m-%d')
) DAY ON DAY.PTL_ID = A.PTL_ID LEFT JOIN ( SELECT SECURITY_COST AS ZQ_Cost, SMV AS ZQ_Value, VAL_DATE, PTL_ID FROM RSK_VALTBL_SUM_ASSET_SUB WHERE SUB_CODE = '702'
AND VAL_DATE = STR_TO_DATE(#{lastMonth},'%Y-%m-%d')
) MONTH ON MONTH.PTL_ID = A.PTL_ID LEFT JOIN ( SELECT SECURITY_COST AS ZQ_Cost, SMV AS ZQ_Value, VAL_DATE, PTL_ID FROM RSK_VALTBL_SUM_ASSET_SUB WHERE SUB_CODE = '702'
AND VAL_DATE = STR_TO_DATE(#{earlyYear},'%Y-%m-%d')
) YEAR ON YEAR.PTL_ID = A.PTL_ID LEFT JOIN ( SELECT VAL_DATE, SECURITY_COST, PTL_ID FROM RSK_VALTBL_SUM_ASSET_SUB WHERE SUB_CODE = '920' ) T9 ON T9.PTL_ID = A.PTL_ID AND T9.VAL_DATE = A.VAL_DATE LEFT JOIN ( SELECT VAL_DATE, SECURITY_COST, PTL_ID FROM RSK_VALTBL_SUM_ASSET_SUB WHERE SUB_CODE = '921' ) T10 ON T10.PTL_ID = A.PTL_ID AND T9.VAL_DATE = A.VAL_DATE ) T LEFT JOIN CHB_ASSET_INFO T1 ON T1.ASSET_CODE = T.PTL_ID
AND T.PTL_ID IN
#{item}
